using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading;

public static class LauncherTests {
    static int count;
    static void Assert(bool condition,string message){if(!condition)throw new Exception(message);count++;}
    static void Reject(Action run,string message){bool rejected=false;try{run();}catch{rejected=true;}Assert(rejected,message);}
    static ContentPackage Package(string id,string source){return new ContentPackage{Id=id,Name=id,Kind="car",ArchiveRoot=id,Url=new Uri("https://assets.example.test/car.7z"),Sha256=new string('a',64),Bytes=1,ExpandedBytes=3,Checks=new[]{new AssetCheck{Path="data.acd",Sha256=ContentInstaller.HashFile(Path.Combine(source,"data.acd")),Bytes=3}}};}
    public static int Main(string[] args){try{
        if(args.Length!=1||!Path.IsPathRooted(args[0]))throw new Exception("Pass an absolute scratch directory");string root=Path.Combine(args[0],Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
        foreach(string bad in new[]{"../outside","root/../../outside","C:/outside","root/file:ads","root/CON.txt","root/file.","root/sub\\file","root/a\nb"})Reject(()=>ContentInstaller.ArchiveName(bad,"root"),"Unsafe archive path accepted");
        ContentInstaller.ArchiveName("root/skins/blue skin/body.dds","root");count++;
        foreach(string bad in new[]{"matrixgames://join?game=assetto-corsa&server=a&host=evil","matrixgames://join?game=halo&server=a","matrixgames://join?game=assetto-corsa&server=a\n","https://join?game=assetto-corsa&server=a"})Reject(()=>JoinLink.Server(bad),"Unsafe protocol accepted");
        Assert(JoinLink.Server("matrixgames://join?game=assetto-corsa&server=managed-110")=="managed-110","Join link failed");
        Reject(()=>JoinLink.Server("matrixgames://join?game=assetto-corsa&server=managed-110&model=car_one"),"Car selection belongs to the game's join step");
        Assert(Program.ProtocolCommand(@"C:\Test User\Launcher.exe")=="\"C:\\Test User\\Launcher.exe\" \"%1\"","Protocol quoting");
        string source=Path.Combine(root,"source","fixture");Directory.CreateDirectory(source);File.WriteAllText(Path.Combine(source,"data.acd"),"abc",new UTF8Encoding(false));var package=Package("fixture",source);
        var manifest=new AssetManifest{Game="assetto-corsa",Revision=new string('b',64),Assets=new[]{package}};string game=Path.Combine(root,"game"),library=Path.Combine(root,"library");Directory.CreateDirectory(game);var vault=new AssetVault(library);
        string archive=Path.Combine(root,"fixture.tar");using(var p=Process.Start(new ProcessStartInfo{FileName=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),"tar.exe"),Arguments="-cf \""+archive+"\" -C \""+Path.GetDirectoryName(source)+"\" fixture",UseShellExecute=false,CreateNoWindow=true})){p.WaitForExit();Assert(p.ExitCode==0,"Fixture archive creation");}
        package.Sha256=ContentInstaller.HashFile(archive);package.Bytes=new FileInfo(archive).Length;Directory.CreateDirectory(Path.Combine(library,"downloads"));File.Copy(archive,Path.Combine(library,"downloads",package.Sha256+".7z"));
        Assert(vault.Missing(game,manifest).Length==1,"Missing asset detection");vault.Apply("one",game,manifest,CancellationToken.None,null);
        string destination=AssetVault.Destination(game,package),payload=vault.Payload(package);Assert(Junction.Target(destination)==payload,"Game points at shared vault");Assert(File.ReadAllText(Path.Combine(destination,"data.acd"))=="abc","Linked data readable");Assert(!File.Exists(Path.Combine(library,"downloads",package.Sha256+".7z")),"Completed archive removed");
        vault.Apply("two",game,manifest,CancellationToken.None,null);Assert(File.Exists(Path.Combine(library,"servers","two","assets.json")),"Second server records reused asset");Assert(Directory.GetDirectories(Path.Combine(library,"objects")).Length==1,"No duplicated payload");
        string game2=Path.Combine(root,"game2");Directory.CreateDirectory(game2);vault.Apply("three",game2,manifest,CancellationToken.None,null);Assert(Junction.Target(AssetVault.Destination(game2,package))==payload,"Cached asset reused without network");
        string game3=Path.Combine(root,"game3"),existing=AssetVault.Destination(game3,package);Directory.CreateDirectory(existing);File.WriteAllText(Path.Combine(existing,"data.acd"),"old");vault.Apply("four",game3,manifest,CancellationToken.None,null);string backup=Directory.GetDirectories(Path.Combine(game3,".matrixgames-backups")).Single();Assert(File.ReadAllText(Path.Combine(backup,"data.acd"))=="old","Original files backed up");
        string game4=Path.Combine(root,"game4"),installed=AssetVault.Destination(game4,package);Directory.CreateDirectory(installed);File.Copy(Path.Combine(source,"data.acd"),Path.Combine(installed,"data.acd"));vault.Apply("five",game4,manifest,CancellationToken.None,null);Assert(Junction.Target(installed)==null,"Existing matching game data stays in place");
        string outside=Path.Combine(root,"unrelated");Directory.CreateDirectory(outside);string game5=Path.Combine(root,"game5"),external=AssetVault.Destination(game5,package);Directory.CreateDirectory(Path.GetDirectoryName(external));Junction.Create(external,outside);Reject(()=>vault.Apply("six",game5,manifest,CancellationToken.None,null),"External links must be preserved");Assert(Junction.Target(external)==outside,"External link unchanged");
        var cancelled=new CancellationTokenSource();cancelled.Cancel();Reject(()=>vault.Apply("seven",game,manifest,cancelled.Token,null),"Cancellation honored");Assert(File.ReadAllText(Path.Combine(payload,"data.acd"))=="abc","Cancel preserves shared files");
        string game6=Path.Combine(root,"game6"),rollback=AssetVault.Destination(game6,package);Directory.CreateDirectory(rollback);File.WriteAllText(Path.Combine(rollback,"original.txt"),"preserve");Reject(()=>vault.Link(game6,rollback,Path.Combine(root,"missing-payload"),CancellationToken.None),"Invalid link fails");Assert(File.ReadAllText(Path.Combine(rollback,"original.txt"))=="preserve","Failed link restores original directory");
        Directory.CreateDirectory(Path.Combine(installed,"data"));Assert(!package.Matches(installed),"Unpacked physics override is not accepted as matching");
        Reject(()=>ContentInstaller.ValidateListing("fixture/data.acd\n","lrwxrwxrwx 1 0 0 3 Jan 1 00:00 fixture/data.acd -> outside\n",package),"Archive symlink rejected");
        Reject(()=>ContentInstaller.ValidateListing("fixture/data.acd\nfixture/DATA.acd\n","-rw-r--r-- 1 0 0 1 Jan 1 00:00 fixture/data.acd\n-rw-r--r-- 1 0 0 2 Jan 1 00:00 fixture/DATA.acd\n",package),"Duplicate Windows paths rejected");
        var settings=new LauncherSettings{LibraryDirectory=library,SteamDirectory=Path.Combine(root,"Steam"),DriverName="Fixture"};settings.Games["assetto-corsa"]=new GameLocations{InstallDirectory=game,DocumentsDirectory=Path.Combine(root,"Documents")};string settingsFile=Path.Combine(root,"settings.json");settings.Save(settingsFile);settings.DriverName="Updated";settings.Save(settingsFile);Assert(LauncherSettings.Load(settingsFile).DriverName=="Updated"&&File.Exists(settingsFile+".previous"),"Settings persist atomically");
        var grant=new Dictionary<string,object>{{"displayName","RoadRunner"},{"schema",3},{"game","assetto-corsa"},{"server","one"},{"track","track"},{"model","fixture"},{"host","203.0.113.8"},{"gamePort",9600},{"httpPort",8081},{"password",""},{"expiresAt",DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()+90000}};var server=new ServerEntry{Id="one",Game="assetto-corsa",Track="track",Models=new[]{"fixture"}};AssettoCorsa.ValidateGrant(grant,server,"fixture");Assert(AssettoCorsa.RaceConfig(grant,"Driver","76561198000000000","skin","").Contains("SERVER_PORT=9600"),"Race config");Assert(AssettoCorsa.RaceConfig(grant,"Google Full Name","76561198000000000","skin","").Contains("DRIVER_NAME=RoadRunner"),"Account name overrides old local name");grant["displayName"]="bad\n[REMOTE]";Reject(()=>AssettoCorsa.RaceConfig(grant,"Driver","76561198000000000","skin",""),"INI injection rejected");grant["displayName"]="RoadRunner";grant["track"]="other";Reject(()=>AssettoCorsa.ValidateGrant(grant,server,"fixture"),"Changed track rejected");
        // Discover secondary Steam libraries and persist selected content roots.
        string steam=Path.Combine(root,"steam"),second=Path.Combine(root,"secondary"),steamGame=Path.Combine(second,"steamapps","common","assettocorsa");Directory.CreateDirectory(Path.Combine(steam,"steamapps"));Directory.CreateDirectory(steamGame);File.WriteAllText(Path.Combine(steamGame,"acs.exe"),"fixture");File.WriteAllText(Path.Combine(steam,"steam.exe"),"fixture");File.WriteAllText(Path.Combine(steam,"steamapps","libraryfolders.vdf"),"\"libraryfolders\" { \"1\" { \"path\" \""+second.Replace("\\","\\\\")+"\" } }");
        foreach(string selected in new[]{steam,Path.Combine(steam,"steamapps"),Path.Combine(steam,"steam.exe"),steamGame})Assert(ContentDiscovery.SteamInstallations(selected).Contains(steamGame),"Steam library discovery: "+selected);
        settings.SteamDirectory=steam;var locations=new GameLocations{InstallDirectory=Path.Combine(root,"gone"),DocumentsDirectory=Path.Combine(root,"custom-docs"),ContentDirectory=Path.GetDirectoryName(source)};new AssettoCorsa().ResolveLocations(settings,locations);Assert(locations.InstallDirectory==steamGame&&locations.DocumentsDirectory.EndsWith("custom-docs"),"Resolve saved Steam folder, preserve chosen Documents");settings.Games["assetto-corsa"]=locations;settings.Save(settingsFile);Assert(LauncherSettings.Load(settingsFile).Games["assetto-corsa"].ContentDirectory==Path.GetDirectoryName(source),"Existing mods location persists");
        Assert(ContentDiscovery.FindFolder(package,ContentDiscovery.SearchRoots(settings,locations))==source,"Selected mods folder discovery");Assert(ContentDiscovery.FindFolder(package,new[]{source})==source,"Direct asset folder discovery");
        string docAsset=Path.Combine(locations.DocumentsDirectory,"content","cars","fixture");Directory.CreateDirectory(docAsset);File.Copy(Path.Combine(source,"data.acd"),Path.Combine(docAsset,"data.acd"));Assert(ContentDiscovery.FindFolder(package,new[]{locations.DocumentsDirectory})==docAsset,"Documents content discovery");
        File.WriteAllText(Path.Combine(docAsset,"data.acd"),"bad");Assert(ContentDiscovery.FindFolder(package,new[]{locations.DocumentsDirectory})==null,"Wrong physics rejected");Assert(package.Problems(docAsset).Single().Contains("data.acd: checksum differs"),"Specific checksum diagnostic");File.WriteAllText(Path.Combine(docAsset,"data.acd"),"wrong length");Assert(package.Problems(docAsset).Single().Contains("size differs"),"Specific size diagnostic");File.Delete(Path.Combine(docAsset,"data.acd"));Assert(package.Problems(docAsset).Single()=="data.acd: missing","Specific missing file diagnostic");
        var freshVault=new AssetVault(Path.Combine(root,"fresh-library"));string localGame=Path.Combine(root,"local-game");var localPlan=freshVault.Plan(localGame,manifest,new[]{Path.GetDirectoryName(source)});Assert(localPlan.DownloadBytes==0&&localPlan.Choices.Single().Folder==source,"Existing folder eliminates download");freshVault.Apply("local-folder",localGame,manifest,CancellationToken.None,null,localPlan);Assert(Junction.Target(AssetVault.Destination(localGame,package))==source&&!Directory.Exists(freshVault.Payload(package)),"Link existing source without duplicate payload");Assert(File.ReadAllText(Path.Combine(source,"data.acd"))=="abc","Source content unchanged");
        File.WriteAllText(Path.Combine(source,"ui-custom.json"),"personal settings");var installedPlan=freshVault.Plan(localGame,manifest,new string[0]);Assert(installedPlan.Choices.Length==0&&installedPlan.DownloadBytes==0,"Installed required files match despite optional metadata");
        string archiveGame=Path.Combine(root,"archive-game");var archivePlan=freshVault.Plan(archiveGame,manifest,new[]{root});Assert(archivePlan.DownloadBytes==0&&archivePlan.Choices.Single().Archive==archive,"Local verified archive eliminates download");freshVault.Apply("local-archive",archiveGame,manifest,CancellationToken.None,null,archivePlan);Assert(File.Exists(archive)&&package.Matches(AssetVault.Destination(archiveGame,package)),"Install local archive and preserve original download");
        var changedVault=new AssetVault(Path.Combine(root,"changed-library"));string changedGame=Path.Combine(root,"changed-game");var changedPlan=changedVault.Plan(changedGame,manifest,new[]{source});File.WriteAllText(Path.Combine(source,"data.acd"),"bad");Reject(()=>changedVault.Apply("changed-source",changedGame,manifest,CancellationToken.None,null,changedPlan),"Changed local source cannot fall back to network");Assert(!Directory.Exists(AssetVault.Destination(changedGame,package)),"Changed source never installed");File.WriteAllText(Path.Combine(source,"data.acd"),"abc");Reject(()=>freshVault.Link(localGame,source,source,CancellationToken.None),"Cannot link a folder to itself");Assert(File.Exists(Path.Combine(source,"data.acd")),"Self-link rejection preserves source");
        var moving=new LauncherSettings{LibraryDirectory=library};moving.SelectLibrary(Path.Combine(root,"new-library"));Assert(moving.PreviousLibraries.Contains(library),"Changing library retains previous location");var moveVault=new AssetVault(moving.LibraryDirectory);var movePlan=moveVault.Plan(Path.Combine(root,"moved-game"),manifest,ContentDiscovery.SearchRoots(moving,new GameLocations()));Assert(movePlan.DownloadBytes==0&&movePlan.Choices.Single().Folder==payload,"Changed library reuses old cached assets");moving.SelectLibrary(moving.LibraryDirectory);Assert(moving.PreviousLibraries.Length==1,"Repeated saves do not duplicate previous libraries");moving.SelectLibrary(Path.GetPathRoot(root));Assert(moving.LibraryDirectory==Path.GetPathRoot(root),"Drive root is a valid library selection");
        var display=new ServerEntry{Game="assetto-corsa",Name="Fixture server",Track="track",Models=new[]{"fixture"},Online=true,Players=1,Capacity=21};display.ModelNames["fixture"]="Fixture Car";Assert(display.ToString().Contains("Assetto Corsa")&&display.Summary.Contains("Fixture Car")&&display.Summary.Contains("track"),"Server game and requirements shown");Assert(AssettoCarWindow.Requirements(installedPlan).Contains("Installed")&&AssettoCarWindow.Requirements(archivePlan).Contains("Install existing archive"),"Car selection describes installed and reusable assets");
        RuntimeInstallTests.Run(root);
        // Scratch is retained for inspection. Never recursively delete junction-bearing fixtures.
        Console.WriteLine(count+" launcher checks passed. Fixture: "+root);return 0;
    }catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
